1	import assert from "node:assert/strict";
2	import { test } from "node:test";
3	import { TodoStore } from "../src/todos.ts";
4	
5	test("add trims the title and starts open", () => {
6	  const store = new TodoStore();
7	  assert.deepEqual(store.add("  Buy milk "), { id: 1, title: "Buy milk", done: false });
8	});
9	
10	test("add rejects an empty title", () => {
11	  assert.throws(() => new TodoStore().add("   "), /required/);
12	});
13	
14	test("toggle flips done", () => {
15	  const store = new TodoStore();
16	  const { id } = store.add("Walk the dog");
17	  assert.equal(store.toggle(id)?.done, true);
18	  assert.equal(store.toggle(id)?.done, false);
19	});
20	
21	test("remove deletes the todo", () => {
22	  const store = new TodoStore();
23	  const { id } = store.add("Call mom");
24	  assert.equal(store.remove(id), true);
25	  assert.deepEqual(store.list(), []);
26	});
